    #[test]
    fn remove_child_preserves_survivor_paths_and_allows_end_reattach() {
        let document = document(
            r#"<main id="mount"><p id="first">first</p><p id="gone">gone</p><p id="last">last</p><p id="status">idle</p></main>"#,
        );
        let mut runtime = ScriptRuntime::new(document.clone());
        runtime
            .execute(
                r#"
                const mount = document.getElementById("mount");
                const gone = document.getElementById("gone");
                const last = document.getElementById("last");
                let clicks = 0;
                gone.addEventListener("click", () => clicks = clicks + 1);
                mount.removeChild(gone);
                const afterRemoval = (document.getElementById("gone") === null) + "|" + last.textContent;
                mount.appendChild(gone);
                gone.click();
                document.getElementById("status").textContent = afterRemoval + "|" + document.getElementById("gone").textContent + "|" + last.textContent + "|" + clicks;
                "#,
            )
            .expect("removeChild should preserve survivor handles");
        let status = document
            .borrow()
            .find_element_by_id("status")
            .expect("status should exist");
        assert_eq!(
            document.borrow().element_text_content(&status).as_deref(),
            Some("true|last|gone|last|1")
        );
    }

    #[test]
    fn insert_before_preserves_existing_element_handles() {
        let document = document(
            r#"<main id="mount"><p id="first">first</p><p id="middle">middle</p><p id="last">last</p><p id="status">idle</p></main>"#,
        );
        let mut runtime = ScriptRuntime::new(document.clone());
        runtime
            .execute(
                r#"
                const mount = document.getElementById("mount");
                const middle = document.getElementById("middle");
                const last = document.getElementById("last");
                let events = "";
                last.addEventListener("click", () => events = events + "last");
                const activate = last.click;
                const setAttribute = last.setAttribute;
                const getAttribute = last.getAttribute;
                const inserted = document.createElement("p");
                inserted.id = "inserted";
                inserted.textContent = "inserted";
                mount.insertBefore(inserted, middle);
                middle.textContent = "middle shifted";
                last.textContent = "last shifted";
                activate();
                setAttribute("data-state", "survived");
                document.getElementById("status").textContent =
                    inserted.textContent + "|" + middle.textContent + "|" + last.textContent + "|" + last.parentNode.id + "|" + events + "|" + getAttribute("data-state");
                "#,
            )
            .expect("insertBefore should preserve survivor handles");
        let status = document
            .borrow()
            .find_element_by_id("status")
            .expect("status should exist");
        assert_eq!(
            document.borrow().element_text_content(&status).as_deref(),
            Some("inserted|middle shifted|last shifted|mount|last|survived")
        );
        assert_eq!(
            document.borrow().find_element_by_id("inserted"),
            Some(vec![0, 1])
        );
        assert_eq!(
            document.borrow().find_element_by_id("middle"),
            Some(vec![0, 2])
        );
        assert_eq!(
            document.borrow().find_element_by_id("last"),
            Some(vec![0, 3])
        );
    }

    #[test]
    fn insert_before_moves_attached_nodes_and_keeps_runtime_state_with_them() {
        let document = document(
            r#"<main id="source"><button id="move">move</button><p id="stay">stay</p></main><main id="target"><p id="reference">reference</p><p id="status">idle</p></main>"#,
        );
        let mut runtime = ScriptRuntime::new(document.clone());
        runtime
            .execute(
                r#"
                const move = document.getElementById("move");
                const stay = document.getElementById("stay");
                const target = document.getElementById("target");
                const reference = document.getElementById("reference");
                let clicks = 0;
                move.addEventListener("click", () => clicks = clicks + 1);
                target.insertBefore(move, reference);
                stay.textContent = "stay shifted";
                reference.textContent = "reference shifted";
                move.textContent = move.parentNode.id;
                move.click();
                document.getElementById("status").textContent =
                    move.textContent + "|" + stay.textContent + "|" + reference.textContent + "|" + clicks;
                "#,
            )
            .expect("insertBefore should move attached nodes");
        let status = document
            .borrow()
            .find_element_by_id("status")
            .expect("status should exist");
        assert_eq!(
            document.borrow().element_text_content(&status).as_deref(),
            Some("target|stay shifted|reference shifted|1")
        );
        assert_eq!(
            document.borrow().find_element_by_id("move"),
            Some(vec![1, 0])
        );
        assert_eq!(
            document.borrow().find_element_by_id("stay"),
            Some(vec![0, 0])
        );
        assert_eq!(
            document.borrow().find_element_by_id("reference"),
            Some(vec![1, 1])
        );
    }

